for(const [name,lat,lng]of labelData)L.marker([lat,lng],{icon:L.divIcon({className:'state-label',html:name,iconSize:[22,12]}),interactive:false,keyboard:false}).addTo(map);
const markerLayer=L.layerGroup().addTo(map),routeLayer=L.layerGroup().addTo(map),endpointLayer=L.layerGroup().addTo(map);
