function validate(raw){
 raw=upgradePlanPreferences(raw);
 if(!raw||raw.version!==1||!Array.isArray(raw.selected)||!Array.isArray(raw.custom))throw Error('Unrecognized plan format');
 const s={...structuredClone(defaults),...raw.settings};
 const bounded=(n,min,max)=>typeof n==='number'&&Number.isFinite(n)&&n>=min&&n<=max;
 if(!['compare','drive','fly'].includes(s.alaskaMode)||!Number.isInteger(s.remoteBufferDays)||!bounded(s.remoteBufferDays,0,30)||!bounded(s.flightDayHours,8,20)||!bounded(s.remoteRoadMph,25,65))throw Error('Invalid remote travel assumptions');
 if(!Array.isArray(s.customAirports)||s.customAirports.length>30||s.customAirports.some(a=>!a||!/^[A-Z0-9]{3,5}$/.test(a.code)||!bounded(a.lat,24,50)||!bounded(a.lng,-125,-66)||typeof a.name!=='string'||a.name.length>100))throw Error('Invalid custom airport');
 const airportCodes=[...MAINLAND_AIRPORTS,...s.customAirports].map(a=>a.code);
 if(new Set(airportCodes).size!==airportCodes.length||!Array.isArray(s.airportCodes)||!s.airportCodes.length||s.airportCodes.some(c=>!airportCodes.includes(c)))throw Error('Enable at least one valid mainland airport');
 s.customAirports=s.customAirports.map(a=>({id:'airport-'+a.code,code:a.code,name:a.name,lat:a.lat,lng:a.lng}));
 if(!s.remoteWindows||typeof s.remoteWindows!=='object'||Object.entries(s.remoteWindows).some(([id,w])=>!REMOTE_PARKS.some(p=>p.id===id)||(w!==null&&(!validMD(w.start)||!validMD(w.end)))))throw Error('Transport windows need valid MM-DD dates, or both dates blank');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(s.startDate)||!Number.isFinite(dateOf(s.startDate).getTime())||iso(dateOf(s.startDate))!==s.startDate)throw Error('Invalid departure date');
 for(const [k,min,max]of [['duration',1,1500],['comfort',1,10],['stretch',1,10],['maxDrive',1,10],['averageMph',15,75],['distanceFactor',1,3],['breakPercent',0,50],['seasonDetourPercent',0,75],['defaultDays',1,90],['restDays',0,365],['detourHours',0,12]])if(!bounded(s[k],min,max))throw Error(`Invalid ${k}`);
 if(s.comfort>s.stretch||s.stretch>s.maxDrive)throw Error('Driving thresholds must increase from comfortable to hard limit');
 if(!['balanced','relaxed','efficient'].includes(s.pace)||!['season','shortest','quiet'].includes(s.objective)||!['open','return','custom'].includes(s.endMode)||!['park','highlights','uniform'].includes(s.stayMode))throw Error('Invalid trip options');
 const validPoint=p=>p&&bounded(p.lat,24,50)&&bounded(p.lng,-125,-66)&&typeof p.name==='string'&&p.name.length<=100;
 if(!validPoint(s.start)||!validPoint(s.endLocation))throw Error('Locations must be in the contiguous United States');
 s.end=s.endMode==='return'?{...s.start,id:'finish'}:s.endMode==='custom'?{...s.endLocation,id:'finish'}:null;
 const custom=raw.custom.map(c=>{
  if(!validPoint(c)||typeof c.id!=='string'||!c.id.startsWith('custom-')||!bounded(c.days,1,365)||!Number.isInteger(c.days))throw Error('Invalid personal stop');
  return {id:c.id,name:c.name,shortName:c.name,kind:String(c.kind||'Other destination').slice(0,100),type:'custom',lat:c.lat,lng:c.lng,days:c.days};
 });
 if(new Set(custom.map(c=>c.id)).size!==custom.length||custom.length>100)throw Error('Duplicate or excessive personal stops');
 const allowed=new Set([...baseSites.map(s=>s.id),...custom.map(s=>s.id)]);
 const priorities=validatePriorities(raw.priorities,allowed);
 const days={};for(const [id,n]of Object.entries(raw.days||{})){if(!allowed.has(id)||!bounded(n,1,365)||!Number.isInteger(n))throw Error('Invalid stay length');days[id]=n;}
 const rules={};for(const [id,r]of Object.entries(raw.rules||{})){
  if(!allowed.has(id))throw Error('Unknown site in seasonal rules');
  for(const key of ['ideal','bad','quiet'])if(!Array.isArray(r[key])||r[key].some(n=>!Number.isInteger(n)||n<1||n>12))throw Error('Season rules require months 1–12');
  if(r.scores&&(!Array.isArray(r.scores)||r.scores.length!==12||r.scores.some(q=>!bounded(q,0,10))))throw Error('Season quality requires 12 scores from 0 to 10');
  if(r.closure&&(!validMD(r.closure.start)||!validMD(r.closure.end)))throw Error('Invalid closure dates');
  rules[id]={ideal:r.ideal,bad:r.bad,quiet:r.quiet,scores:r.scores||MONTHS.map((_,i)=>monthlyQuality(r,i+1)),closure:r.closure?{start:r.closure.start,end:r.closure.end,status:'user-entered annual rule',note:'User-entered assumption; not independently verified.'}:null};
 }
 const calibration=structuredClone(INITIAL_CALIBRATION);
 for(const row of CALIBRATION_ROUTES){const value=raw.calibration?.[row.id];if(!value)continue;
  if((value.miles!==null&&!bounded(value.miles,.1,10000))||(value.hours!==null&&!bounded(value.hours,.01,250)))throw Error('Invalid route calibration values');
  calibration[row.id]={miles:value.miles,hours:value.hours,include:value.include!==false};
 }
 return {version:1,preferencesRevision:3,settings:s,custom,selected:[...new Set(raw.selected.filter(id=>allowed.has(id)))],days,priorities,rules,calibration};
}
function validMD(s){if(typeof s!=='string'||!/^\d{2}-\d{2}$/.test(s))return false;const d=dateOf(`2040-${s}`);return Number.isFinite(d.getTime())&&iso(d).slice(5)===s;}
// Full destination days for signature sights; travel and access buffers remain separate.
const highlightDays={yell:4,grte:2,glac:3,yose:3,grca:2,zion:2,brca:1,arch:1,cany:2,care:1,romo:2,olym:3,mora:2,noca:2,redw:2,sequ:2,kica:1,deva:2,jotr:1,badl:1,thro:2,acad:2,grsm:3,ever:2,bisc:1,drto:1,dena:3,wrst:3,glba:2,katm:2,lacl:2,gaar:2,kova:1,bela:1,hale:2,havo:2,npsa:2,viis:2,jeff:1};
function rebuild(){sites=[...baseSites.map(s=>{const rule=state.rules[s.id];return {...s,priority:state.priorities[s.id]??s.priority??1,remote:s.remote?{...s.remote,window:state.settings.remoteWindows?.[s.id]===null?null:state.settings.remoteWindows?.[s.id]||s.remote.window}:undefined,days:state.days[s.id]??(s.type==='park'&&state.settings.stayMode==='uniform'?state.settings.defaultDays:s.type==='park'&&state.settings.stayMode==='highlights'?Math.min(s.days,highlightDays[s.id]??Math.max(1,Math.ceil(s.days/2))):s.days),profile:rule?{...s.profile,ideal:rule.ideal,bad:rule.bad,quiet:rule.quiet,scores:rule.scores,quality:'User-edited monthly quality assumptions'}:s.profile,closure:rule?rule.closure:s.closure};}),...state.custom.map(s=>({...s,priority:state.priorities[s.id]??1,days:state.days[s.id]??s.days}))];lookup=new Map(sites.map(s=>[s.id,s]));}
function save(){try{localStorage.setItem('long-way-plan-v1',JSON.stringify(state));}catch{toast('Browser storage is unavailable. Use Export plan to save your work.');}}
function renderTransport(){renderTransportSettings(state.settings,values=>{try{const next=structuredClone(state);Object.assign(next.settings,values);state=validate(next);changed();renderTransport();toast('Transport assumptions saved. Find my route will compare the updated options.');}catch(e){toast(e.message);}},region=>{state.selected=[...new Set([...state.selected,...sites.filter(s=>s.remote?.region===region).map(s=>s.id)])];changed();renderAll();$('mapRegion').value=region;showRegion(region);toast(`${REGION_NAMES[region]} parks added to the trip.`);},toast);}
function changed(){revision++;const canceled=!!worker;if(worker){worker.terminate();worker=null;$('optimize').disabled=false;$('optimize').textContent='Find my route →';}if(result||canceled){$('routeStatus').textContent='INPUTS CHANGED · RECALCULATE';$('suggestionSection').hidden=true;routeLayer.clearLayers();$('routeOutput').innerHTML='<div class="empty-state"><p>Inputs changed. Find my route will calculate an updated itinerary.</p></div>';result=null;renderMarkers();}save();}
function toast(message,persistent=false){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);if(!persistent)toast.timer=setTimeout(()=>$('toast').hidden=true,6500);}
function renderAll(){renderMarkers();renderList();renderCustom();renderSummary();renderEndpoints();syncLens();renderCalibration();renderTransport();if(activeId)renderDetail(activeId);}
function setSelected(id,selected){state.selected=state.selected.filter(x=>x!==id);if(selected)state.selected.push(id);changed();renderAll();}
function renderSummary(){const selected=state.selected.map(id=>lookup.get(id)).filter(Boolean),s=state.settings;$('selectedCount').textContent=selected.length;$('selectionSummary').textContent=`${selected.length} places · ${selected.reduce((n,s)=>n+s.days,0)} full days + travel · ${s.duration}-day target · ${s.endMode==='return'?'round trip to '+s.start.name:s.endMode==='open'?'one-way finish':'finish: '+s.end.name}`;$('optimize').disabled=!selected.length;$('autoMonth').checked=s.autoMonth;$('inventoryNote').textContent=`${baseSites.filter(s=>s.type==='park').length} US national parks · ${baseSites.filter(s=>s.type==='site').length} other CONUS NPS locations. Remote access is modeled separately. CONUS site inventory: Nov 2022.`;}
function color(s){if(s.type==='custom')return '#846286';if(lens==='selection')return state.selected.includes(s.id)?'#375b43':'#a6b39b';const date=dateOf(`2040-${String(month).padStart(2,'0')}-15`);return season(s,date)==='closed'?'#777e85':qualityColor(seasonQuality(s,date));}
function renderMarkers(){markerLayer.clearLayers();markers.clear();const selected=new Set(state.selected),numbers=visitNumbers(result);
 for(const s of sites){
  if(!visibleSite(s,shownTypes))continue;
  const stopNumber=lens==='selection'?numbers.get(s.id):undefined;
  const isSelected=selected.has(s.id),type=markerType(s),size=markerSize(s,isSelected);
  const marker=L.marker([s.lat,s.lng],{keyboard:false,zIndexOffset:isSelected?700:0,icon:L.divIcon({className:`site-marker marker-${type.id}${isSelected?' is-selected':''}`,html:shapeSvg(type.shape,color(s),isSelected)+(stopNumber===undefined?'':`<span class="site-stop-number" aria-hidden="true">${stopNumber}</span>`),iconSize:[size,size],iconAnchor:[size/2,size/2]})});
  marker.bindTooltip(()=>{const el=document.createElement('div'),d=dateOf(`2040-${String(month).padStart(2,'0')}-15`),q=seasonQuality(s,d);el.textContent=`${s.shortName} · ${s.designation||s.kind||type.label} · ${season(s,d)==='closed'?'Closed at mid-month':q===null?'No seasonal score':q+'/10 in '+MONTHS[month-1]} · Priority ${s.priority}/5 · ${isSelected?'Selected':'Not selected'}`;return el;});
  const activate=()=>{if(pick)map.fire('click',{latlng:L.latLng(s.lat,s.lng)});else openDetail(s.id);};
  marker.on('click',e=>{L.DomEvent.stopPropagation(e);activate();});marker.addTo(markerLayer);markers.set(s.id,marker);
  const el=marker.getElement();el.setAttribute('aria-label',`${stopNumber===undefined?'':'Stop '+stopNumber+' · '}${s.shortName} · ${s.designation||type.label} · ${isSelected?'selected':'not selected'}`);el.setAttribute('role','button');el.setAttribute('tabindex','0');el.dataset.mapSite=s.id;el.dataset.markerShape=type.shape;el.dataset.selected=String(isSelected);if(stopNumber!==undefined)el.dataset.stopNumber=String(stopNumber);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate();}});
 }
}
function renderEndpoints(){endpointLayer.clearLayers();const s=state.settings,points=s.endMode==='return'?[[s.start,'START / FINISH']]:[[s.start,'START'],...(s.end?[[s.end,'FINISH']]:[])];for(const [p,label]of points){L.marker([p.lat,p.lng],{alt:`${label}: ${p.name}`,icon:L.divIcon({className:'start-marker',iconSize:[14,14],iconAnchor:[7,7]})}).bindTooltip(()=>{const e=document.createElement('span');e.textContent=`${label}: ${p.name}`;return e;}).addTo(endpointLayer);}document.querySelector('.intro-note .pill').textContent=`${s.start.name} → ${s.end?.name||'anywhere'}`;}
function renderList(){const q=$('search').value.trim().toLowerCase(),filter=$('typeFilter').value;const visible=sites.filter(s=>(filter==='all'?s.type!=='custom':filter==='selected'?state.selected.includes(s.id):filter==='remote'?!!s.remote:s.type==='park')&&`${s.name} ${s.state||''} ${s.designation||''}`.toLowerCase().includes(q));
 $('siteList').innerHTML=visible.length?visible.map(s=>`<div class="site-row"><input type="checkbox" data-select="${escape(s.id)}" aria-label="Include ${escape(s.shortName)}" ${state.selected.includes(s.id)?'checked':''}><button class="site-name" data-detail="${escape(s.id)}"><strong>${escape(s.shortName)}</strong><small>${escape(s.state||s.kind||'')} · ${s.type==='park'?'National park':escape(s.designation||'Personal stop')}${s.access?' · '+escape(s.access.mode):''}${s.type==='park'?' · Priority '+s.priority+'/5':''}</small></button><i class="dot" style="background:${color(s)}" aria-label="${escape(s.profile?season(s,dateOf(`2040-${String(month).padStart(2,'0')}-15`)):'personal')}"></i><label class="days-wrap"><input type="number" min="1" max="365" value="${s.days}" data-days="${escape(s.id)}" aria-label="Full days at ${escape(s.shortName)}">d</label></div>`).join(''):'<p class="muted">No matching places.</p>';
}
$('siteList').addEventListener('click',e=>{const b=e.target.closest('[data-detail]');if(b)openDetail(b.dataset.detail);});
$('siteList').addEventListener('change',e=>{if(e.target.dataset.select)setSelected(e.target.dataset.select,e.target.checked);if(e.target.dataset.days){const n=Number(e.target.value);if(!Number.isInteger(n)||n<1||n>365){toast('Choose 1–365 full days.');renderList();return;}state.days[e.target.dataset.days]=n;changed();rebuild();renderSummary();if(activeId)renderDetail(activeId);}});
$('search').addEventListener('input',renderList);$('typeFilter').addEventListener('change',renderList);
$('selectAll').onclick=()=>{state.selected=[...new Set([...state.selected,...sites.filter(s=>s.type==='park').map(s=>s.id)])];changed();renderAll();toast('All 64 national parks selected. Off-mainland parks are optimized as regional excursions.');};
$('reset').onclick=()=>{state.selected=[];changed();renderAll();};
$('month').oninput=()=>{month=Number($('month').value);syncLens();renderMarkers();renderList();};
$('autoMonth').onchange=()=>{state.settings.autoMonth=$('autoMonth').checked;changed();renderSummary();toast(state.settings.autoMonth?'Full 12-month route search enabled. Find my route will compare every month.':'Departure-month search disabled; the saved departure date will be used.');};
function syncLens(){
 map.getContainer().classList.toggle('drawing-circle',pick==='circle');
 document.querySelectorAll('[data-lens]').forEach(b=>{b.classList.toggle('active',b.dataset.lens===lens);b.setAttribute('aria-pressed',String(b.dataset.lens===lens));});
 $('month').disabled=lens==='selection';
 const monthName=new Date(Date.UTC(2040,month-1,1)).toLocaleString('en-US',{month:'long',timeZone:'UTC'});$('monthValue').textContent=monthName;$('month').setAttribute('aria-valuetext',monthName);
 if(lens==='season'||pick==='circle'){
  if(map.hasLayer(routeLayer))map.removeLayer(routeLayer);
  $('mapCaption').textContent=pick==='circle'?'Every enabled location stays visible. The circle previews eligible places; selected places are larger. Route labels are temporarily hidden.':'All enabled location types stay visible. Color = draft 0–10 seasonal quality; grey = closed. Selected places are larger. Sliding the month does not recalculate your itinerary.';
 }else{
  if(!map.hasLayer(routeLayer))routeLayer.addTo(map);
  $('mapCaption').textContent='Selected visible stops are enlarged. Numbers follow every destination, including OCONUS parks. Tan = draft roads; purple = flights / regional transfers. Connections are schematic.';
 }
 // Keep seasonal categories out of the selected-route view.
 $('mapLegend').hidden=lens!=='season';
}
function setLens(value){lens=value;syncLens();renderMarkers();renderList();}
document.querySelectorAll('[data-lens]').forEach(b=>b.onclick=()=>setLens(b.dataset.lens));
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
function switchTab(tab){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));for(const id of ['places','trip','custom'])$(id+'Panel').hidden=id!==tab;}
function fit(){const points=state.selected.map(id=>lookup.get(id)).filter(Boolean).map(s=>[s.lat,s.lng]);if(points.length)map.fitBounds(L.latLngBounds([...points,[state.settings.start.lat,state.settings.start.lng],...(state.settings.end?[[state.settings.end.lat,state.settings.end.lng]]:[])]),{padding:[45,55],maxZoom:6});else map.fitBounds([[24,-125],[50,-66]]);}
$('fit').onclick=fit;
function showRegion(region){const bounds={conus:[[24,-125],[50,-66]],alaska:[[55,-170],[71.5,-130]],hawaii:[[18.6,-160.5],[22.5,-154.5]],virgin:[[18.24,-65.05],[18.46,-64.55]],samoa:[[-14.45,-170.9],[-14.1,-170.45]],all:[[-15,-174],[72,-64]]};map.fitBounds(bounds[region],{padding:[25,30],maxZoom:9});}
$('mapRegion').onchange=()=>showRegion($('mapRegion').value);
let circleEdge=null;
function beginPick(mode){cancelPick();pick=mode;$('circle').classList.toggle('active',mode==='circle');$('circle').setAttribute('aria-pressed',String(mode==='circle'));map.getContainer().style.cursor='crosshair';syncLens();toast(mode==='circle'?'Click a center, move to preview, then click the outer edge to add places. Escape cancels.':`Click the map to choose the ${mode==='custom'?'personal stop':mode} location.`,true);}
$('circle').onclick=()=>{if(pick==='circle')cancelPick();else beginPick('circle');};
$('pickStart').onclick=()=>beginPick('start');$('pickEnd').onclick=()=>beginPick('finish');$('pickCustom').onclick=()=>beginPick('custom');
function cancelPick(){pick=null;circleCenter=null;circleEdge=null;map.getContainer().style.cursor='';$('circle').classList.remove('active');$('circle').setAttribute('aria-pressed','false');$('circlePreview').hidden=true;for(const m of markers.values())m.getElement()?.classList.remove('circle-new','circle-kept');if(circleLayer){map.removeLayer(circleLayer);circleLayer=null;}$('toast').hidden=true;syncLens();}
document.addEventListener('keydown',e=>{if(e.key==='Escape')cancelPick();});
function previewCircle(edge){
 circleEdge=edge;const radius=map.distance(circleCenter,edge);
 if(circleLayer)circleLayer.setRadius(radius);else circleLayer=L.circle(circleCenter,{radius,color:'#375b43',weight:1.5,fillOpacity:.08,interactive:false}).addTo(map);
 const candidates=circleCandidates(sites.filter(s=>visibleSite(s,shownTypes)),circleCenter,haversine(circleCenter,edge),$('circleScope').value),ids=new Set(candidates.map(s=>s.id)),selected=new Set(state.selected),kept=candidates.filter(s=>selected.has(s.id)).length;
 for(const [id,m]of markers){const el=m.getElement();el?.classList.toggle('circle-new',ids.has(id)&&!selected.has(id));el?.classList.toggle('circle-kept',ids.has(id)&&selected.has(id));}
 $('circlePreview').hidden=false;const text=`Inside circle: ${candidates.length} eligible · ${candidates.length-kept} new · ${kept} already selected. Click the edge to add; Escape cancels.`;if($('circlePreview').textContent!==text)$('circlePreview').textContent=text;
}
$('circleScope').onchange=()=>{if(pick==='circle'&&circleCenter&&circleEdge)previewCircle(circleEdge);};
map.on('mousemove',e=>{if(pick==='circle'&&circleCenter)previewCircle(e.latlng);});
map.on('click',e=>{if(!pick)return;const {lat,lng}=e.latlng;if(pick!=='circle'&&(lat<24||lat>50||lng< -125||lng> -66)){toast('This first map supports the contiguous United States.');return;}
 if(pick==='circle'){
  if(!circleCenter){circleCenter=e.latlng;previewCircle(e.latlng);return;}
  const candidates=circleCandidates(sites,circleCenter,haversine(circleCenter,e.latlng),$('circleScope').value),added=candidates.filter(s=>!state.selected.includes(s.id)).length;state.selected=[...new Set([...state.selected,...candidates.map(s=>s.id)])];cancelPick();if(added)changed();renderAll();toast(`${added} new places added · ${candidates.length-added} already selected. Places outside the circle kept.`);return;
 }
 const mode=pick;const prefix=mode==='finish'?'end':mode;$(prefix+'Lat').value=lat.toFixed(4);$(prefix+'Lng').value=lng.toFixed(4);cancelPick();switchTab(mode==='custom'?'custom':'trip');toast('Coordinates filled in. Save the form to apply the location.');
});
function openDetail(id){if(pick)return;if(!lookup.has(id)){document.getElementById('result-'+id)?.scrollIntoView({behavior:'smooth',block:'start'});return;}activeId=id;renderDetail(id);markers.get(id)?.setZIndexOffset(900);$('detail').scrollIntoView({behavior:'smooth',block:'nearest'});}
function renderDetail(id){
 const s=lookup.get(id);if(!s){$('detail').hidden=true;return;}$('detail').hidden=false;
 renderLocationDetail({site:s,baseSite:baseSites.find(p=>p.id===id),selected:state.selected.includes(id),
  onToggle:()=>setSelected(id,!state.selected.includes(id)),
  onSaveVisit:values=>{try{const next=structuredClone(state);next.priorities[id]=values.priority;next.days[id]=values.days;state=validate(next);changed();rebuild();renderAll();toast('Visit priority and full days saved. Recalculate to apply them.');}catch(e){toast(e.message);}},
  onResetPriority:()=>{delete state.priorities[id];changed();rebuild();renderAll();toast('Default priority restored. Stay days and season rules were preserved.');},
  onClose:()=>{$('detail').hidden=true;activeId=null;},
  onSave:rule=>{state.rules[id]=rule;changed();rebuild();renderAll();toast('Numeric seasonal scores saved. Recalculate to apply them.');},
  onReset:()=>{delete state.rules[id];changed();rebuild();renderAll();},onError:toast});
}

function fillSettings(){const s=state.settings;for(const key of ['startDate','duration','objective','seasonDetourPercent','pace','comfort','stretch','maxDrive','averageMph','distanceFactor','breakPercent','stayMode','defaultDays','restDays','detourHours','endMode'])$(key).value=s[key];$('autoMonth').checked=s.autoMonth;for(const key of ['Name','Lat','Lng']){$('start'+key).value=s.start[key.toLowerCase()];$('end'+key).value=s.endLocation[key.toLowerCase()];}$('endFields').hidden=s.endMode!=='custom';$('uniformDaysField').hidden=s.stayMode!=='uniform';$('seasonDetourPercent').disabled=s.objective==='shortest';endRequired();}
$('objective').onchange=()=>{$('seasonDetourPercent').disabled=$('objective').value==='shortest';};
function endRequired(){for(const id of ['endName','endLat','endLng'])$(id).required=$('endMode').value==='custom';}
$('endMode').onchange=()=>{$('endFields').hidden=$('endMode').value!=='custom';endRequired();};
$('stayMode').onchange=()=>{$('uniformDaysField').hidden=$('stayMode').value!=='uniform';};
$('restoreStays').onclick=()=>{for(const s of baseSites)if(s.type==='park')delete state.days[s.id];changed();rebuild();fillSettings();renderAll();toast('Selected stay preset restored. Personal stops and other NPS day edits were preserved.');};
$('settingsForm').onsubmit=e=>{e.preventDefault();try{const next=structuredClone(state),s=next.settings;for(const key of ['startDate','objective','pace','endMode','stayMode'])s[key]=$(key).value;for(const key of ['duration','comfort','stretch','maxDrive','averageMph','distanceFactor','breakPercent','seasonDetourPercent','defaultDays','restDays','detourHours'])s[key]=Number($(key).value);s.autoMonth=$('autoMonth').checked;s.start={id:'start',name:$('startName').value.trim(),lat:Number($('startLat').value),lng:Number($('startLng').value)};s.endLocation={name:$('endName').value.trim()||'Finish',lat:Number($('endLat').value),lng:Number($('endLng').value)};state=validate(next);changed();rebuild();renderAll();toast('Trip settings saved. Find my route will use these inputs.');}catch(e){toast(e.message);}};
$('customForm').onsubmit=e=>{e.preventDefault();const id='custom-'+crypto.randomUUID();const next=structuredClone(state);next.custom.push({id,name:$('customName').value.trim(),shortName:$('customName').value.trim(),kind:$('customKind').value,type:'custom',days:Number($('customDays').value),lat:Number($('customLat').value),lng:Number($('customLng').value)});next.selected.push(id);try{state=validate(next);changed();rebuild();renderAll();$('customForm').reset();$('customDays').value=3;toast('Personal stop added and included in the trip.');}catch(e){toast(e.message);}};
function renderCustom(){$('customList').innerHTML=state.custom.map(s=>`<div class="custom-item"><input type="checkbox" data-custom-select="${escape(s.id)}" aria-label="Include ${escape(s.name)}" ${state.selected.includes(s.id)?'checked':''}><p>${escape(s.name)}<small>${escape(s.kind)} · ${lookup.get(s.id).days} full days</small></p><button data-custom-delete="${escape(s.id)}" aria-label="Delete ${escape(s.name)}">×</button></div>`).join('');}
$('customList').onchange=e=>{if(e.target.dataset.customSelect)setSelected(e.target.dataset.customSelect,e.target.checked);};
$('customList').onclick=e=>{const id=e.target.dataset.customDelete;if(id){state.custom=state.custom.filter(s=>s.id!==id);state.selected=state.selected.filter(s=>s!==id);delete state.days[id];changed();rebuild();renderAll();}};
$('optimize').onclick=()=>{if(!state.selected.length)return;if(worker)worker.terminate();const started=revision;worker=new Worker('./worker.mjs',{type:'module'});$('optimize').disabled=true;$('optimize').textContent='Sketching your route…';$('routeOutput').innerHTML='<div class="loading">Comparing visit orders and seasonal fit. You can keep exploring the map.</div>';$('routeStatus').textContent='CALCULATING LOCALLY';$('suggestionSection').hidden=true;
 worker.onmessage=({data})=>{if(started!==revision)return;if(data.progress){const p=data.progress;$('routeStatus').textContent=`MONTH ${Math.min(p.completed+1,p.total)} OF ${p.total}`;$('routeOutput').innerHTML=`<div class="loading">Fully optimizing ${MONTHS[dateOf(p.startDate).getUTCMonth()]} ${p.startDate.slice(0,4)} · ${p.completed} of ${p.total} months complete. You can keep exploring the map.</div>`;return;}worker.terminate();worker=null;$('optimize').disabled=false;$('optimize').innerHTML='Find my route <span>→</span>';if(data.error){toast(`Route calculation failed: ${data.error}`);$('routeOutput').textContent='Could not calculate this plan.';return;}result=data.result;renderRoute(data.suggestions);};
 worker.onerror=()=>{worker?.terminate();worker=null;$('optimize').disabled=false;$('optimize').textContent='Find my route →';$('routeOutput').textContent='The calculation could not finish. Your selected places are saved.';toast('Local optimizer error. Your plan is still saved.');};
 worker.postMessage({stops:state.selected.map(id=>lookup.get(id)).filter(Boolean),settings:state.settings,candidates:sites.filter(s=>s.type==='site'&&!state.selected.includes(s.id))});
};
function routeStop(id){return lookup.get(id)||result?.nodes?.find(s=>s.id===id);}
function renderRoute(suggestions){if(!result)return;const r=result;$('routeStatus').textContent='SUGGESTED ROUTE · ESTIMATES';routeLayer.clearLayers();
 const metric=(value,label)=>`<div class="metric"><strong>${value}</strong><span>${label}</span></div>`;
 const conflicts=r.visits.filter(v=>v.status==='difficult'||v.status==='closed');
 $('routeOutput').innerHTML=`<div class="metric-grid">${metric(format(r.miles),'estimated road miles')}${metric(r.parkDays,'full destination days')}${metric(r.travelDays+r.transferDays,'drive + transfer days')}${metric(r.restDays,'reserved rest days')}${metric(r.remaining>=0?r.remaining:Math.abs(r.remaining),r.remaining>=0?'days under target':'days over target')}${metric(conflicts.length,'seasonal conflicts')}</div><p class="route-explanation"><strong>${nice(r.startDate)}, ${r.startDate.slice(0,4)} → ${nice(r.endDate)}, ${r.endDate.slice(0,4)}</strong> · ${r.totalDays} days allocated, including ${r.waitDays} closure / transport-window wait days. ${format(r.hours)} estimated driving hours; ${r.longDays} driving days above your comfort target. ${r.restDays} rest days are reserved at the end of this draft calendar; remaining flex time is not assigned. Small-circle and dashed straight connections are not verified roads, and remote links are schematic. Suggested order uses a heuristic, not a guaranteed global optimum.</p>${r.remaining<0?'<div class="warning">This plan exceeds your reporting target. The target does not affect route ranking or shorten stays. Adjust the target, full park days, driving pace, rest reserve or selections after reviewing the route. <button type="button" data-edit-trip class="text-button">Adjust trip settings ↗</button></div>':''}${conflicts.length?`<div class="warning">Difficult-season visits: ${conflicts.map(v=>escape(routeStop(v.id).shortName)).join(', ')}. Seasonal preferences are soft constraints; inspect the dates before adopting this route.</div>`:''}${r.warnings.length?`<details class="warning"><summary>Closure and scheduling notes (${r.warnings.length})</summary>${r.warnings.map(w=>`<p>${escape(w)}</p>`).join('')}</details>`:''}<div class="route-list">${r.visits.map((v,i)=>{const s=routeStop(v.id),leg=r.legs[i],label=visitNumberLabel(r,v.id);return `<article class="visit-card"><span class="visit-num ${label.length>2?'is-range':''}">${label}</span><h3><button class="text-button" data-route-detail="${escape(s.id)}">${escape(s.shortName)}</button></h3><p>${nice(v.arrival)}–${nice(addDays(dateOf(v.departure),-1).toISOString().slice(0,10))}, ${v.arrival.slice(0,4)}<br>${v.days} full days${v.excursion?'':' · priority '+v.priority+'/5'}${v.transferDays?` + ${v.transferDays} transfer days`:''}<br>Getting here: ~${format(leg.miles)} mi · ${leg.hours.toFixed(1)} h<br>${leg.days} driving day${leg.days===1?'':'s'}${leg.days?` · ~${leg.dailyHours.toFixed(1)} h/day`:''}</p><span class="status-label ${v.status}">${v.status==='unknown'?'Personal stop':v.status==='ideal'?'Ideal*':v.status==='difficult'?'Difficult*':v.status==='closed'?'Closure / access conflict':'Mixed*'}</span></article>`;}).join('')}</div>`;
 if(r.excursions?.length)$('routeOutput').insertAdjacentHTML('beforeend',transportResults(r,lookup));
 const finishLeg=r.legs.find(l=>l.to==='finish');
 if(finishLeg){
  const home=state.settings.endMode==='return',arrival=iso(addDays(dateOf(finishLeg.depart),finishLeg.days));
  $('routeOutput').querySelector('.route-list').insertAdjacentHTML('beforeend',`<article class="visit-card finish-card"><span class="visit-num">⌂</span><h3>${home?'Return home':'Finish'} · ${escape(state.settings.end.name)}</h3><p>~${format(finishLeg.miles)} mi · ${finishLeg.hours.toFixed(1)} driving h<br>${finishLeg.days} driving day${finishLeg.days===1?'':'s'}${finishLeg.days?` · ~${finishLeg.dailyHours.toFixed(1)} h/day`:''}<br>Arrival: ${nice(arrival)}, ${arrival.slice(0,4)}<br>Before unplaced rest-day reserve.</p><span class="status-label">Included in totals</span></article>`);
 }
 const estimateNotes=r.legs.filter(l=>l.cautions?.length).map(l=>`${l.from==='start'?state.settings.start.name:routeStop(l.from)?.shortName||l.from} → ${l.to==='finish'?state.settings.end.name:routeStop(l.to)?.shortName||l.to}: ${l.cautions.join(' ')}`);
 if(estimateNotes.length)$('routeOutput').insertAdjacentHTML('beforeend',`<details class="estimate-notes"><summary>Route-estimate notes (${estimateNotes.length})</summary><p>Canada is an acceptable corridor. Actual roads, border delays, terrain and speed variation are not modeled.</p>${estimateNotes.map(s=>`<p>${escape(s)}</p>`).join('')}</details>`);
 const finishNote=document.createElement('p');finishNote.className='route-explanation';finishNote.textContent=`${state.settings.endMode==='return'?'Round trip: the final drive back to '+state.settings.start.name+' is included.':state.settings.end?'One-way trip: the final drive to '+state.settings.end.name+' is included.':'Open-ended trip: no return drive is included.'} Mainland driving estimates use ${state.settings.averageMph} mph${r.excursions?.length?`; Alaska / regional roads use ${state.settings.remoteRoadMph} mph`:""}, plus 15 minutes per nonzero leg. Canada is an acceptable corridor; border time is not included.`;$('routeOutput').querySelector('.metric-grid').after(finishNote);
 const tradeoff=document.createElement('p');tradeoff.className='route-explanation tradeoff-note';tradeoff.textContent=r.excursions?.length?`Mainland ordering: ~${format(r.mainlandMiles)} miles against a ~${format(r.baselineMiles)}-mile baseline, with the saved ${r.detourPercent}% seasonal distance budget. Airport detours, Alaska/Canadian driving and regional rental driving are added separately to the road total. Commercial/regional transport adds ~${r.flightHours.toFixed(1)} hours; airfare is excluded from ranking. Total driving: ${r.hours.toFixed(1)} h + ${r.breakHours.toFixed(1)} h stop allowance. The joint road/flight insertion search is a heuristic.`:`Distance-first baseline found: ~${format(r.baselineMiles)} miles. This route: +${format(r.extraMiles)} miles (${r.baselineMiles?(r.extraMiles/r.baselineMiles*100).toFixed(1):'0.0'}%), within a ${r.detourPercent}% extra-distance limit. ${state.settings.objective==='shortest'?'Driving distance is the priority.':'Driving cost remains in the seasonal/crowd objective; numeric 0–10 quality uses progressively larger penalties for poor conditions.'} Total driving: ${r.hours.toFixed(1)} h + ${r.breakHours.toFixed(1)} h stop allowance = ${r.elapsedHours.toFixed(1)} h elapsed (${state.settings.breakPercent}% extra). Daily driving limits exclude this stop allowance.`;finishNote.after(tradeoff);
 const qualityMetric=$('routeOutput').querySelector('.metric:last-child');qualityMetric.querySelector('strong').textContent=r.quality===null?'—':r.quality.toFixed(1)+'/10';qualityMetric.querySelector('span').textContent='day-weighted seasonal quality';
 const qualityNote=document.createElement('p');qualityNote.className='route-explanation';qualityNote.textContent=`Seasonal quality is averaged across ${r.qualityDays} modeled destination days, using the dates actually spent at each stop. Personal stops without scores are excluded. Each park day’s seasonal penalty is multiplied by its editable personal priority (1–5). The quality average above remains day-weighted without priority, so it still describes the conditions. Trip days are a reporting target and do not affect ranking. Closures remain separate exclusions.`;tradeoff.after(qualityNote);
 if(r.monthResults)renderMonthComparison(r);
 $('routeOutput').querySelectorAll('.visit-card').forEach((card,i)=>{const v=r.visits[i];if(!v)return;const badge=card.querySelector('.status-label');badge.textContent=v.status==='closed'?'Closure conflict':v.quality===null?'No seasonal score':v.quality.toFixed(1)+'/10 quality';badge.title=v.minQuality===null?'Personal stop':`Lowest day: ${v.minQuality}/10; quality uses all full stay days.`;});
 $('routeOutput').querySelectorAll('.visit-card').forEach((card,i)=>{const leg=r.legs[i];if(!leg)return;const p=document.createElement('p');p.className='elapsed-note';p.textContent=`~${leg.elapsedHours.toFixed(1)} h including ${state.settings.breakPercent}% for stops${leg.days?` · ~${(leg.elapsedHours/leg.days).toFixed(1)} h/day elapsed`:''}`;card.append(p);});
 const latlng=p=>[p.lat,p.lng];
 const stops=r.order.map(id=>routeStop(id));let previous=state.settings.start;
 for(const s of stops){const road=s.access?.gateway||s;L.polyline([latlng(previous.access?.gateway||previous),latlng(road)],{color:'#a87945',weight:2,dashArray:'6 7',opacity:.8,interactive:false}).addTo(routeLayer);if(s.access)L.polyline([latlng(road),latlng(s)],{color:'#658a9b',weight:2,dashArray:'2 6',interactive:false}).addTo(routeLayer);previous=s;}
 if(state.settings.end)L.polyline([latlng(previous.access?.gateway||previous),latlng(state.settings.end)],{color:'#a87945',weight:2,dashArray:'6 7',interactive:false}).addTo(routeLayer);
 for(const block of r.excursions||[])for(const t of block.transport){if(!t.from||!t.to)continue;L.polyline([latlng(t.from),latlng(t.to)],{color:t.kind==='drive'?'#a87945':'#6b779d',weight:2,dashArray:t.kind==='drive'?'6 7':'2 6',interactive:false}).addTo(routeLayer);}

 $('suggestionSection').hidden=!suggestions.length;$('suggestionList').innerHTML=suggestions.map(d=>{const s=routeStop(d.id);return `<article class="suggestion-card"><p class="eyebrow">${escape(s.state)} · OPTIONAL NPS STOP</p><h3>${escape(s.name)}</h3><p>~${Math.round(d.extraHours*60)} extra driving minutes · ~${format(d.extraMiles)} extra miles<br>+ ${s.days} full visit day${s.days===1?'':'s'} · recalculation may add driving days.</p><button data-add-suggestion="${escape(s.id)}">Include & recalculate ↗</button></article>`;}).join('');setLens('selection');fit();
}
function renderMonthComparison(r){
 const ranks=new Map([...r.monthResults].sort((a,b)=>a.score-b.score).map((m,i)=>[m.startDate,i+1]));
 const section=document.createElement('section');section.className='month-comparison';
 section.innerHTML=`<p class="eyebrow">12 MONTHS · 12 FULL ROUTE SEARCHES</p><h3>Find your best departure window.</h3><p class="fineprint">Every month starts on the first in ${escape(r.searchYear)} and receives the same full optimizer search. Rank balances your selected priority, driving, the distance budget and calendar constraints. It may differ from the ranking of average quality alone. Select a month to inspect its route.</p><div class="month-table-scroll"><table><thead><tr><th>Departure</th><th>Rank</th><th>Quality</th><th>Est. miles</th><th>Allocated days</th><th>Low-score visits</th><th>Route</th></tr></thead><tbody>${r.monthResults.map((m,i)=>`<tr class="${m.startDate===r.startDate?'shown-month':''}"><th scope="row">${MONTHS[dateOf(m.startDate).getUTCMonth()]} ${m.startDate.slice(0,4)}</th><td>${ranks.get(m.startDate)}${ranks.get(m.startDate)===1?' ★':''}</td><td>${m.quality===null?'—':m.quality.toFixed(1)+'/10'}</td><td>${format(m.miles)}</td><td>${m.totalDays}${m.remaining<0?' · over target':''}</td><td>${m.visits.filter(v=>v.minQuality!==null&&v.minQuality<=3).length}</td><td><button data-month-result="${i}" ${m.startDate===r.startDate?'disabled':''} aria-label="View ${MONTHS[dateOf(m.startDate).getUTCMonth()]} ${m.startDate.slice(0,4)} route">${m.startDate===r.startDate?'Shown':'View route'}</button></td></tr>`).join('')}</tbody></table></div>`;
 $('routeOutput').querySelector('.route-list').before(section);
}
$('routeOutput').onclick=e=>{if(e.target.closest('[data-edit-trip]')){switchTab('trip');$('settingsForm').scrollIntoView({behavior:'smooth',block:'start'});} const b=e.target.closest('[data-route-detail]');if(b)openDetail(b.dataset.routeDetail);const monthButton=e.target.closest('[data-month-result]');if(monthButton&&result?.monthResults){const all=result.monthResults,searchYear=result.searchYear;result={...all[Number(monthButton.dataset.monthResult)],monthResults:all,searchYear};const suggestions=detours(sites.filter(s=>s.type==='site'&&!state.selected.includes(s.id)),result.order.map(id=>routeStop(id)),state.settings);renderRoute(suggestions);}};
$('suggestionList').onclick=e=>{const b=e.target.closest('[data-add-suggestion]');if(b){setSelected(b.dataset.addSuggestion,true);$('optimize').click();}};
function closeExportMenu(focus=false){$('exportMenu').hidden=true;$('export').setAttribute('aria-expanded','false');if(focus)$('export').focus();}
$('export').onclick=()=>{const open=$('exportMenu').hidden;$('exportMenu').hidden=!open;$('export').setAttribute('aria-expanded',String(open));$('exportNote').textContent=result?'Exports the route currently shown, including individual OCONUS parks and transport days. CSV/XLSX are reports; use JSON to restore a plan.':'No route calculated: CSV/XLSX will list selected places without itinerary dates or travel estimates. Find my route first for a complete itinerary.';if(open)$('exportMenu').querySelector('button').focus();};
document.addEventListener('click',e=>{if(!e.target.closest('#exportWrap'))closeExportMenu();});
$('exportWrap').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeExportMenu(true);}if((e.key==='ArrowDown'||e.key==='ArrowUp')&&!$('exportMenu').hidden){e.preventDefault();const items=[...$('exportMenu').querySelectorAll('button')],i=items.indexOf(document.activeElement);items[(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length].focus();}});
function downloadTrip(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
$('exportMenu').onclick=e=>{const b=e.target.closest('[data-export-format]');if(!b)return;const kind=b.dataset.exportFormat;
 try{
  if(kind==='json'){downloadTrip(new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString(),estimatesNote:'Draft monthly assumptions and travel estimates. JSON restores plan inputs; recalculate the itinerary.'},null,2)],{type:'application/json'}),'the-long-way-plan.json');toast('Restorable JSON plan backup exported.');}
  else{const tables=exportTables({state,sites,result}),filename='the-long-way-'+(result?'itinerary-'+result.startDate:'selected-places');
   if(kind==='csv')downloadTrip(new Blob([csvText(tables.itinerary)],{type:'text/csv;charset=utf-8'}),filename+'.csv');
   else{if(!globalThis.XLSX)throw Error('The Excel export library could not load. CSV and JSON are still available.');downloadTrip(new Blob([xlsxBytes(tables,globalThis.XLSX)],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),filename+'.xlsx');}
   toast((kind==='csv'?'CSV':'Excel')+(result?' itinerary exported.':' selected-place report exported; calculate a route to include dates and travel.'));
  }
  closeExportMenu(true);
 }catch(error){toast('Export failed: '+error.message);}
};
function calibrationData(){return CALIBRATION_ROUTES.map(row=>{const a=row.from==='cos'?defaults.start:routeStop(row.from),b=routeStop(row.to);return {...row,a,b,airMiles:haversine(roadPoint(a),roadPoint(b)),...(state.calibration[row.id]||{miles:null,hours:null})};});}
function renderCalibration(){
 const rows=calibrationData().filter(row=>!row.legacy||row.miles!==null||row.hours!==null);
 $('calibrationRows').innerHTML=rows.map(row=>{const a=roadPoint(row.a),b=roadPoint(row.b),current=travel(row.a,row.b,state.settings);const url=`https://www.google.com/maps/dir/?api=1&origin=${a.lat},${a.lng}&destination=${b.lat},${b.lng}&travelmode=driving`;return `<tr><th scope="row"><a href="${escape(url)}" target="_blank" rel="noopener">${escape(row.name)} ↗</a><small>${escape(row.note)}</small></th><td><input type="number" min="0.1" max="10000" step="0.1" value="${row.miles??''}" data-calibration="${row.id}" data-calibration-field="miles" aria-label="Maps miles: ${escape(row.name)}" placeholder="miles"></td><td><input type="text" inputmode="decimal" value="${row.hours??''}" data-calibration="${row.id}" data-calibration-field="hours" aria-label="Maps driving hours: ${escape(row.name)}" placeholder="h:mm or decimal"></td><td>~${format(current.miles)} mi · ${current.hours.toFixed(1)} h driving<small>${current.elapsedHours.toFixed(1)} h with ${state.settings.breakPercent}% for stops</small></td></tr>`;}).join('');
 $('calibrationRows').querySelectorAll('tr').forEach((tr,i)=>{const row=rows[i],cell=document.createElement('td');cell.innerHTML=`<input type="checkbox" data-calibration="${row.id}" data-calibration-field="include" aria-label="Use in fit: ${escape(row.name)}" ${row.include!==false?'checked':''}>`;tr.querySelector('td:last-child').before(cell);if(Number.isFinite(row.miles)&&row.miles<row.airMiles*.98)tr.querySelector('th').insertAdjacentHTML('beforeend',`<small class="calibration-mismatch">Check endpoints: ${row.miles} road miles is below ~${Math.round(row.airMiles)} straight-line miles between these pins. Saved, but excluded from fitting.</small>`);});
 const fit=fitCalibration(rows);$('applyCalibration').disabled=fit.count<2||!fit.valid;
 $('calibrationSummary').textContent=fit.count?`${fit.count} complete, included comparisons${fit.skipped?`; ${fit.skipped} endpoint mismatch excluded`:''}. Suggested average driving speed: ${fit.averageMph.toFixed(1)} mph; road-distance multiplier: ${fit.distanceFactor.toFixed(3)}. Median per-route ratios keep the longest drive from dominating. ${fit.valid?'The stop allowance is added afterward, not fitted into driving speed.':'Values fall outside the supported range; check matched endpoints, miles and driving hours.'}`:`Enter Maps miles and driving hours to compare them with this draft.${fit.skipped?' Some entries need matched endpoints before fitting.':''}`;
}
$('calibrationRows').onchange=e=>{const id=e.target.dataset.calibration,field=e.target.dataset.calibrationField;if(!id||!field)return;
 if(field==='include'){state.calibration[id]={...(state.calibration[id]||{miles:null,hours:null}),include:e.target.checked};save();renderCalibration();return;}
 const value=e.target.value.trim()===''?null:field==='hours'?parseDrivingHours(e.target.value):Number(e.target.value);
 if(value!==null&&(!Number.isFinite(value)||value<=0||value>(field==='hours'?250:10000))){toast('Enter positive miles and a driving time such as 5:30 or 5.5.');renderCalibration();return;}
 state.calibration[id]={...(state.calibration[id]||{miles:null,hours:null}),[field]:value};save();renderCalibration();
};
$('applyCalibration').onclick=()=>{const fit=fitCalibration(calibrationData());if(fit.count<2||!fit.valid)return;state.settings.averageMph=+fit.averageMph.toFixed(1);state.settings.distanceFactor=+fit.distanceFactor.toFixed(3);changed();fillSettings();renderCalibration();toast('Calibration applied. Recalculate the route to use the updated mileage and speed assumptions.');};
$('openCalibration').onclick=()=>$('calibrationSection').scrollIntoView({behavior:'smooth',block:'start'});
$('import').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2e6)throw Error('Plan file is too large.');const next=validate(JSON.parse(await f.text()));state=next;result=null;routeLayer.clearLayers();$('routeOutput').innerHTML='<div class="empty-state"><p>Plan imported. Find my route will recalculate the itinerary.</p></div>';$('suggestionSection').hidden=true;changed();rebuild();fillSettings();renderAll();toast('Plan imported and saved locally.');}catch(err){toast(`Import failed: ${err.message}`);}finally{e.target.value='';}};
$('dataInfo').onclick=()=>{$('aboutContent').innerHTML=`<ul><li><strong>Inventory:</strong> ${baseSites.length} mapped locations, including ${baseSites.filter(s=>s.type==='park').length} national parks. The 12 off-mainland parks use approximate access locations and regional excursions. <a href="${metadata.source}" target="_blank" rel="noopener">Public NPS boundary layer</a>, last edited Nov 2022; downloaded Oct 27, 2026. This is not a current completeness audit. Boundary centroids are approximate and are not entrances.</li><li><strong>Distances:</strong> great-circle distance × the adjustable road factor (default 1.246). Driving time = estimated miles ÷ the adjustable average speed (default 60.6 mph) + 15 minutes per nonzero leg. An additional 10% elapsed-time allowance for stops is shown separately by default. Initial calibration uses your two supplied Maps comparisons; one model cannot reproduce every road type. No traffic, roads, towing restrictions, terrain, fuel stops or breaks modeled. These values are placeholders; some geographic pairs are especially inaccurate.</li><li><strong>Off-mainland transport:</strong> All enabled mainland airports can connect to every region. Flight times, park stay allowances, regional access, weather buffers and Alaska service windows are provisional. Fly-outs return to their original mainland airport. Alaska driving uses Canadian highway waypoints and still includes flights/boats to remote parks. Road and flight time and priority-weighted seasonal fit affect ranking; the trip-day target and airfare do not. No flight schedules, fares, charter bookings or rental permissions are verified. Regional road speed is separately adjustable.</li><li><strong>Season lens:</strong> Monthly 0–10 quality scores and quieter-month flags are coarse editable assumptions. Scores assess draft weather/hiking suitability, not measured forecasts; partial-month and whole-park closure rules remain separate. Quieter months are not measured visitation statistics. Low crowd levels do not imply good weather or access. No future forecasts are claimed.</li><li><strong>Closures:</strong> only Isle Royale's published annual Nov 1–Apr 15 closure is seeded as a whole-stop restriction. <a href="https://www.nps.gov/isro/planyourvisit/hours.htm" target="_blank" rel="noopener">NPS annual rule</a>. Other closures remain explicitly unverified. Road/area closures, multiple windows and live alerts are not implemented. Personal edits become user-entered rules.</li><li><strong>Heat:</strong> Death Valley's summer penalty reflects <a href="https://www.nps.gov/deva/planyourvisit/summer.htm" target="_blank" rel="noopener">NPS heat guidance</a>; exact monthly scores are draft assumptions.</li><li><strong>Remote access:</strong> Isle Royale, Dry Tortugas and Channel Islands use approximate mainland gateways plus two placeholder transfer days. No schedules, fares or service-day constraints checked. Alaska, Hawaii and territories are outside this first map.</li><li><strong>Calendar:</strong> drive days and remote transfer days never consume requested full visit days. Closure wait days count toward the trip. Rest days are reserved at the end; unallocated flex days are not distributed. Fixed-date appointments and manual route locks are future work.</li><li><strong>Optimization:</strong> A distance-first baseline is refined with systematic 2-opt and nearby relocation moves. Seasonal/crowd search retains driving cost and stays within an editable extra-distance budget (default 15% above that baseline). Numeric seasonal penalties increase as the square of the quality deficit, so low-quality days matter substantially more than small differences near 10/10. Full independent monthly searches are compared when enabled. Closure conflicts can create waiting and overrun. It does not prove a global optimum. Google API calls: zero.</li><li><strong>Local storage:</strong> browser storage remembers settings; Export provides a backup. No account, analytics or online map tiles. Leaflet (BSD-2-Clause), topojson-client (ISC), us-atlas (ISC) and public US Census map geometry are bundled locally.</li></ul>`;$('about').showModal();};$('closeAbout').onclick=()=>$('about').close();





